#!/usr/bin/env bash
# Bundle item 188 pa37_summary (thread "Site: run the meeting archive", 23 Nov 2569 Bangkok)
# Routine content update (AUTO UPDATES, Sukit 11 Nov 2569), Public Administration 2569 archive.
# Main committee meeting 37/2569 (Wed 18 Nov 2569): the published Senate summary (สรุปผลการประชุม, ref 11232488, Rpublic 1)
# replaces the "upcoming" agenda card: headline, summary, 6 items with resolutions (draft Domestic Violence Act sections 6-15,
# 5 areas of recommendations; letter to the Treasury Department on a state-land complaint; progress on a village-head
# qualification complaint in Phang Nga; work of the 3 subcommittees). Agency names only; no complainant or private person named.
# Changes (committee-archive-2569 only; home page cards follow through run_bundle.sh hub_snap_sync.py, m/37.html and the
# search index through run_bundle's seo.py / search steps):
#   index.html  DATA (37 replaced, live media kept), TL (37's planned-meeting entry removed: the meeting has been held),
#               SHARE_V (37 -> new card), UPDATED (max)
#   meetings.json (37 replaced); s/37.html replaced (only if it is the live version this item was built on, or already new);
#   img/s/37-aba30d59.jpg new; s/v-37-pre.html: the meeting headline in its 2 descriptions; i18n-en.json +18 lines (add-only).
# SELF-CONTAINED (shared folder over its cap): the payload is embedded at the end of this file; no payload folder.
# Surgical JSON-level edits of the live lines/files (a full build drifts from live). Idempotent; no git, no network. Needs $A69.
set -euo pipefail
T=188_pa37_summary

main() {
  : "${A69:?A69 not set}"
  for f in index.html meetings.json i18n-en.json s/37.html s/v-37-pre.html; do
    test -f "$A69/$f" || { echo "$T: A69/$f missing" >&2; exit 1; }
  done
  local TMP; TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
  payload > "$TMP/p.tgz"
  tar -xzmf "$TMP/p.tgz" -C "$TMP"
  test -f "$TMP/payload.json" -a -f "$TMP/en_add.json" -a -f "$TMP/base_s37.sha256" || { echo "$T: embedded payload broken" >&2; exit 1; }

  # 1) files: the new card (refuse to overwrite a different file of the same name) and the share page (only from the known base)
  mkdir -p "$A69/s" "$A69/img/s"
  f=img/s/37-aba30d59.jpg
  if [ -f "$A69/$f" ] && ! cmp -s "$TMP/files/$f" "$A69/$f"; then echo "$T: $f already exists with other content; not overwriting" >&2; exit 1; fi
  cmp -s "$TMP/files/$f" "$A69/$f" 2>/dev/null || cp -f "$TMP/files/$f" "$A69/$f"; cmp -s "$TMP/files/$f" "$A69/$f"
  f=s/37.html
  if ! cmp -s "$TMP/files/$f" "$A69/$f"; then
    have=$(sha256sum "$A69/$f" | cut -d' ' -f1); want=$(cut -d' ' -f1 "$TMP/base_s37.sha256")
    [ "$have" = "$want" ] || { echo "$T: $f is not the version this item was built on (sha256 $have); not overwriting" >&2; exit 1; }
    cp -f "$TMP/files/$f" "$A69/$f"; cmp -s "$TMP/files/$f" "$A69/$f"
  fi

  # 2) data lines and files
  python3 - "$A69" "$TMP" <<'PY'
import json, os, sys
A69, D = sys.argv[1:3]
P = json.load(open(os.path.join(D, 'payload.json'), encoding='utf-8'))
dec = json.JSONDecoder()
SERS = [lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/'),
        lambda v: json.dumps(v, ensure_ascii=False),
        lambda v: json.dumps(v, ensure_ascii=False, separators=(',', ':')),
        lambda v: json.dumps(v, ensure_ascii=False).replace('</', '<\\/')]
changed = []

def put(path, text):
    if open(path, encoding='utf-8').read() != text:
        open(path, 'w', encoding='utf-8').write(text); changed.append(os.path.relpath(path, A69))

class Page:
    def __init__(self, path):
        self.path = path; self.lines = open(path, encoding='utf-8').read().split('\n')
    def edit(self, pfx, fn):
        idx = [k for k, l in enumerate(self.lines) if l.startswith(pfx)]
        assert len(idx) == 1, f'{os.path.basename(self.path)}: {pfx} not found once'
        l = self.lines[idx[0]]; v, e = dec.raw_decode(l[len(pfx):]); rest = l[len(pfx) + e:]
        ser = next((s for s in SERS if pfx + s(v) + rest == l), None)
        assert ser, f'{os.path.basename(self.path)}: {pfx} does not round-trip; not touching it'
        self.lines[idx[0]] = pfx + ser(fn(v)) + rest
    def save(self):
        put(self.path, '\n'.join(self.lines))

def keep_media(old, new):
    out = dict(new); out['media'] = old.get('media', {})
    return {k: out[k] for k in new.keys()}

def upd_meeting(arr, key, new):
    """replace meeting `key` (n, date) with `new`, keeping the live media (videos). The meeting must already be there."""
    i = [k for k, m in enumerate(arr) if (m['n'], m['date']) == key]
    assert len(i) == 1, f'{key} not found once'
    arr[i[0]] = keep_media(arr[i[0]], new)
    return arr

N = P['n']; K = (N, P['date'])
pg = Page(os.path.join(A69, 'index.html'))
pg.edit('const DATA=', lambda a: upd_meeting(a, K, P['data']))
pg.edit('const TL=', lambda v: [x for x in v if not (x[2] == 'cal' and x[5] == 'plan' and x[6] == N
                                                       and str(x[3]).startswith('นัดประชุมครั้งที่'))])
def sv(v):
    v = dict(v); assert str(N) in v, 'SHARE_V has no 37'; v[str(N)] = P['share']; return v
pg.edit('const SHARE_P="",SHARE_V=', sv)
pg.edit('const UPDATED=', lambda v: max(v, P['updated']))
pg.save()

p = os.path.join(A69, 'meetings.json'); raw = open(p, encoding='utf-8').read(); ms = json.loads(raw)
assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, 'meetings.json does not round-trip; not touching it'
put(p, json.dumps(upd_meeting(ms, K, P['json']), ensure_ascii=False, indent=1))

# the pre-meeting video share page describes the meeting by its headline (as v-36-pre does after the 36 summary)
V = P['vpre']; p = os.path.join(A69, V['file']); t = open(p, encoding='utf-8').read()
if t.count(V['new']) != V['count']:
    assert t.count(V['old']) == V['count'], f"{V['file']}: old headline found {t.count(V['old'])} times, expected {V['count']}; not touching it"
    put(p, t.replace(V['old'], V['new']))

# English for the archive (add missing keys only, keep file format and order)
p = os.path.join(A69, 'i18n-en.json'); src = open(p, encoding='utf-8').read(); d = json.loads(src)
end = '\n}\n' if src.endswith('\n}\n') else '\n}'
ren = lambda x: '{\n' + ',\n'.join(json.dumps(a, ensure_ascii=False) + ': ' + json.dumps(b, ensure_ascii=False) for a, b in x.items()) + end
assert ren(d) == src, 'i18n-en.json does not round-trip; not touching it'
for a, b in json.load(open(os.path.join(D, 'en_add.json'), encoding='utf-8')).items():
    d.setdefault(a, b)
put(p, ren(d))
print('188_pa37_summary: changed', len(changed), 'files:', ', '.join(changed) or 'none (already applied)')
PY

  # 3) final check
  python3 - "$A69" <<'PY' || { echo "$T: final check failed" >&2; exit 1; }
import json, os, sys
A = sys.argv[1]
m = [x for x in json.load(open(os.path.join(A, 'meetings.json'), encoding='utf-8')) if x['n'] == 37 and x['date'] == '2026-11-18']
assert len(m) == 1; m = m[0]
assert not m.get('upcoming') and len(m['items']) == 6 and any(d['k'] == 'summary' and d['url'].endswith('ref=11232488') for d in m['docs']), m
assert m['headline'].startswith('ร่าง พ.ร.บ.ความรุนแรงในครอบครัว'), m['headline']
t = open(os.path.join(A, 'index.html'), encoding='utf-8').read()
assert 'img/s/37-aba30d59.jpg' in open(os.path.join(A, 's/37.html'), encoding='utf-8').read()
assert '"นัดประชุมครั้งที่ 37/2569"' not in t
PY
  echo "$T: done"
}

# Embedded payload: tar.gz (files/ = s/37.html + the new card, payload.json = data from the private full build, en_add.json,
# base_s37.sha256 = the live s/37.html this item was built on), base64.
payload() {
  base64 -d <<'B64'
